<?php

const MOD = 1000000007;

function main() {
    $line = trim(fgets(STDIN));
    list($n, $k) = array_map('intval', explode(' ', $line));

    if ($k >= $n) {
        echo 0, "\n";
        return;
    }

    // Precompute factorials up to n
    $fact = array_fill(0, $n + 1, 1);
    for ($i = 1; $i <= $n; ++$i) {
        $fact[$i] = $fact[$i - 1] * $i % MOD;
    }

    // Precompute inverse factorials
    $inv_fact = array_fill(0, $n + 1, 1);
    $inv_fact[$n] = pow_mod($fact[$n], MOD - 2, MOD);
    for ($i = $n - 1; $i >= 0; --$i) {
        $inv_fact[$i] = $inv_fact[$i + 1] * ($i + 1) % MOD;
    }

    // Precompute inverse for 1..n
    $inv = array_fill(0, $n + 1, 1);
    for ($i = 1; $i <= $n; ++$i) {
        $inv[$i] = $inv_fact[$i] * $fact[$i - 1] % MOD;
    }

    // Compute C(n, m) for m from 0 to n
    $C = array_fill(0, $n + 1, 0);
    for ($m = 0; $m <= $n; ++$m) {
        $C[$m] = $fact[$n] * $inv_fact[$m] % MOD;
        $C[$m] = $C[$m] * $inv_fact[$n - $m] % MOD;
    }

    // Compute S(m) for m from 0 to n
    $S = array_fill(0, $n + 1, 0);
    $S[0] = 1;
    for ($m = 1; $m <= $n; ++$m) {
        $S[$m] = $S[$m - 1] * ($m - 1) % MOD;
        if ($m - 1 >= $k) {
            $S[$m] = ($S[$m] + $C[$m - 1] * $inv[$m] % MOD) % MOD;
        }
    }

    // Compute the answer
    $ans = 0;
    for ($m = 1; $m <= $n; ++$m) {
        $term = $C[$m] * $S[$m] % MOD;
        $term = $term * $fact[$n - $m] % MOD;
        $ans = ($ans + $term) % MOD;
    }

    echo $ans, "\n";
}

function pow_mod($base, $exp, $mod) {
    $result = 1;
    while ($exp > 0) {
        if ($exp % 2 == 1) {
            $result = $result * $base % $mod;
        }
        $base = $base * $base % $mod;
        $exp = (int)($exp / 2);
    }
    return $result;
}

main();
?>
