<?php

function main() {
    $line = trim(fgets(STDIN));
    list($n, $k) = array_map('intval', explode(' ', $line));
    $mod = 1000000007;

    if ($n == 1) {
        echo 0 . "\n";
        return;
    }

    // Precompute factorials up to n
    $fact = array_fill(0, $n + 1, 0);
    $fact[0] = 1;
    for ($i = 1; $i <= $n; $i++) {
        $fact[$i] = ($fact[$i - 1] * $i) % $mod;
    }

    // Precompute inverse factorials
    $inv_fact = array_fill(0, $n + 1, 0);
    $inv_fact[$n] = modinv($fact[$n], $mod);
    for ($i = $n - 1; $i >= 0; $i--) {
        $inv_fact[$i] = ($inv_fact[$i + 1] * ($i + 1)) % $mod;
    }

    // Precompute inverse of integers up to n
    $inv = array_fill(0, $n + 1, 0);
    for ($i = 1; $i <= $n; $i++) {
        $inv[$i] = modinv($i, $mod);
    }

    // Compute S(m) for m from 0 to n-1
    $S = array_fill(0, $n, 0);
    $S[0] = 1;
    for ($m = 1; $m <= $n - 1; $m++) {
        $term = ($m * $S[$m - 1]) % $mod;
        if ($m >= $k) {
            $term = ($term + $fact[$m - $k]) % $mod;
        }
        $S[$m] = $term;
    }

    // Compute sum_terms = sum_{m=0}^{n-1} C(n-1, m) * S(m)
    $sum_terms = 0;
    for ($m = 0; $m <= $n - 1; $m++) {
        $comb = ($fact[$n - 1] * $inv_fact[$m]) % $mod;
        $comb = ($comb * $inv_fact[$n - 1 - $m]) % $mod;
        $sum_terms = ($sum_terms + ($comb * $S[$m]) % $mod) % $mod;
    }

    // Compute answer = (n! - sum_terms) mod mod
    $ans = ($fact[$n] - $sum_terms) % $mod;
    if ($ans < 0) {
        $ans += $mod;
    }
    echo $ans . "\n";
}

function modinv($a, $mod) {
    return pow($a, $mod - 2, $mod);
}

main();
?>
