$MOD = 1000000007;
$line = trim(fgets(STDIN));
list($n, $k) = array_map('intval', explode(' ', $line));

if ($n == 1) {
    echo 0;
    exit;
}

// Precompute factorials and inverse factorials up to n
$fact = array_fill(0, $n + 1, 1);
for ($i = 1; $i <= $n; $i++) {
    $fact[$i] = $fact[$i - 1] * $i % $MOD;
}

$inv_fact = array_fill(0, $n + 1, 1);
$inv_fact[$n] = pow($fact[$n], $MOD - 2, $MOD);
for ($i = $n - 1; $i >= 0; $i--) {
    $inv_fact[$i] = $inv_fact[$i + 1] * ($i + 1) % $MOD;
}

function comb($n, $k, $fact, $inv_fact, $MOD) {
    if ($k < 0 || $k > $n) return 0;
    return $fact[$n] * $inv_fact[$k] % $MOD * $inv_fact[$n - $k] % $MOD;
}

// Compute S = sum_{m=0}^{k-1} C(n-1, m)
$S = 0;
for ($m = 0; $m < $k; $m++) {
    if ($m > $n - 1) break;
    $S = ($S + comb($n - 1, $m, $fact, $inv_fact, $MOD)) % $MOD;
}

// Compute T = sum_{m=0}^{k-1} C(n-1, m) * m!
$T = 0;
for ($m = 0; $m < $k; $m++) {
    if ($m > $n - 1) break;
    $term = comb($n - 1, $m, $fact, $inv_fact, $MOD) * $fact[$m] % $MOD;
    $T = ($T + $term) % $MOD;
}

// Answer = (n-1)! * (S - T) mod MOD
$ans = $fact[$n - 1] * ($S - $T) % $MOD;
if ($ans < 0) $ans += $MOD;
echo $ans;
?>
